questionvariables.text:
/* Randomising measurements */

r_p: (rand(4)+6)/10;
h_p: rand(5)+3;

l_b: rand_with_step(20*r_p+1, 20*r_p+10, 1)/10;
h_b: rand_with_step(11, 10*l_b-1, 1)/10;

l_g: rand_with_step(10*l_b+1, 10*l_b+10, 1)/10;
h_g: rand_with_step(10*h_b+1, 10*h_b+9, 1)/10;

/* Solutions */

V_g: (1/3)*h_g*l_g^2;
V_b: h_b*l_b^2;
V_p: h_p*%pi*r_p^2;
V_T: V_g+V_b+V_p;

A_g: 4*(sqrt((l_g/2)^2 + h_g^2)*l_g/2) + l_g^2 - l_b^2;
A_b: 4*(l_b*h_b) + l_b^2 - %pi*r_p^2;
A_p: 2*%pi*r_p*h_p + %pi*r_p^2;
A_T: A_g+A_b+A_p;

feedbackvariables.text:
/* Node 1: Check all parts correct (7) */
node1_test: if ans1=decimalplaces(V_g,3) and ans2=decimalplaces(V_b,3) and ans3=decimalplaces(V_p,3) and (ans4=decimalplaces(V_T,3) or ans4=decimalplaces(V_g,3)+decimalplaces(V_b,3)+decimalplaces(V_p,3)) then 1 else 0;

/* Node 2: Worked solution */

/* Node 3: Check V_g correct (+2) */
/* Node 4: Check V_g incorrectly rounded (+1) */
node4_test: if abs(ans1-V_g) <= 0.01 then 1 else 0;

/* Node 5: Check V_b correct (+2) */
/* Node 6: Check V_b incorrectly rounded (+1) */
node6_test: if abs(ans2-V_b) <= 0.01 then 1 else 0;

/* Node 7: Check V_p correct (+2) */
/* Node 8: Check V_p incorrectly rounded (+1) */
node8_test: if abs(ans3-V_p) <= 0.01 then 1 else 0;

/* Node 9: Check V_T correct (+1) */
node9_test: if ans4=decimalplaces(V_T,3) or ans4=decimalplaces(V_g,3)+decimalplaces(V_b,3)+decimalplaces(V_p,3) then 1 else 0;

/* Node 10: Check V_T consistent with given answers (+1) */
node10_test: if ans4=ans1+ans2+ans3 then 1 else 0;

/* Node 1: Check all parts correct (7) */
node1_test: if ans5=decimalplaces(A_g,3) and ans6=decimalplaces(A_b,3) and ans7=decimalplaces(A_p,3) and (ans8=decimalplaces(A_T,3) or ans8=decimalplaces(A_g,3)+decimalplaces(A_b,3)+decimalplaces(A_p,3)) then 1 else 0;

/* Node 2: Worked solution */

/* Node 3: Check A_g correct (+2) */
/* Node 4: Check A_g incorrectly rounded (+1) */
node4_test: if abs(ans5-A_g) <= 0.01 then 1 else 0;

/* Node 5: Check whether student gave full surface area of pyramid (+1) */
node5_test: if ans5=4*(((l_g/2)^2 + h_g^2)*l_g/2) + l_g^2 then 1 else 0;

/* Node 6: Check A_b correct (+2) */
/* Node 7: Check A_b incorrectly rounded (+1) */
node7_test: if abs(ans6-A_b) <= 0.01 then 1 else 0;

/* Node 8: Check whether student gave full surface area of cuboid (+1) */
node8_test: if ans6=4*(l_b*h_b) + 2*(l_b^2) then 1 else 0;

/* Node 9: Check A_p correct (+2) */
/* Node 10: Check A_p incorrectly rounded (+1) */
node10_test: if abs(ans7-A_p) <= 0.01 then 1 else 0;

/* Node 11: Check whether student gave full surface area of cylinder (+1) */
node11_test: if ans7=2*%pi*r_p*h_p + 2*%pi*r_p^2 then 1 else 0;

/* Node 12: Check A_T correct (+1) */
node12_test: if ans8=decimalplaces(A_T,3) or ans8=decimalplaces(A_g,3)+decimalplaces(A_b,3)+decimalplaces(A_p,3) then 1 else 0;

/* Node 13: Check A_T consistent with given answers (+1) */
node13_test: if ans8=ans5+ans6+ans7 then 1 else 0;
